import {registrationWindow,thaiTime} from './registration-window.js';
export const toThaiInput=ms=>Number.isFinite(ms)?new Date(ms+7*3600000).toISOString().slice(0,16):'';
export function fromThaiInput(value){if(!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(value))return NaN;const ms=Date.parse(value+':00+07:00');return toThaiInput(ms)===value?ms:NaN}
export function mountRegistrationSettings(root,client,event,isCurrent=()=>true){
 let state={...event},busy=false,disposed=false,offset=0,dirty=false,latestVersion=event.scheduleVersion||0;
 const panel=document.createElement('section');panel.className='panel registration-settings';
 panel.innerHTML='<h3>กำหนดเวลารับสมัคร</h3><p class="sub">เวลาไทย (UTC+7) · เปิด–ปิดได้แม้ไม่มีใครเปิดเว็บ · เมื่อที่นั่งเต็มจะหยุดรับสมัคร</p><p class="registration-summary" role="status"></p><form><label>รูปแบบการรับสมัคร<select name="mode"><option value="manual">เปิด–ปิดด้วยตัวเอง</option><option value="scheduled">ตั้งเวลาอัตโนมัติ</option></select></label><div class="schedule-fields"><label>วันและเวลาเปิดรับสมัคร (เวลาไทย)<input type="datetime-local" name="start"></label><label>วันและเวลาปิดรับสมัคร (เวลาไทย)<input type="datetime-local" name="end"></label></div><p class="sub">เปลี่ยนกลับเป็นเปิด–ปิดด้วยตัวเอง จะพักรับสมัครไว้ก่อน · การบันทึกเวลาใหม่ไม่ยกเลิกการพักฉุกเฉิน</p><button class="primary" type="submit">บันทึกการตั้งค่า</button></form><div class="event-state-actions"><button type="button" data-resume></button><button type="button" data-pause>พักรับสมัครทันที</button><button type="button" data-reload>โหลดการตั้งค่าล่าสุด</button></div><p class="schedule-message" role="status"></p>';
 root.append(panel);const form=panel.querySelector('form'),summary=panel.querySelector('.registration-summary'),message=panel.querySelector('.schedule-message'),resume=panel.querySelector('[data-resume]'),pause=panel.querySelector('[data-pause]'),reload=panel.querySelector('[data-reload]');
 const active=()=>!disposed&&isCurrent()&&panel.isConnected;
 function fields(){const scheduled=form.elements.mode.value==='scheduled';panel.querySelector('.schedule-fields').hidden=!scheduled;for(const key of ['start','end'])form.elements[key].required=scheduled}
 function fill(){form.elements.mode.value=state.registrationMode||'manual';form.elements.start.value=toThaiInput(state.opensAtMs);form.elements.end.value=toThaiInput(state.closesAtMs);latestVersion=state.scheduleVersion||0;dirty=false;fields()}
 function draw(){if(!active())return;const window=registrationWindow(state,Date.now()+offset),scheduled=state.registrationMode==='scheduled';summary.textContent=(scheduled?'เปิด '+thaiTime(state.opensAtMs)+' · ปิด '+thaiTime(state.closesAtMs)+' · ':'')+({waiting:'รอเปิดรับสมัครตามกำหนด',closed:'ปิดรับสมัครแล้ว',paused:'พักรับสมัครฉุกเฉิน',invalid:'การตั้งเวลาไม่สมบูรณ์'})[window.reason];if(['manual','open'].includes(window.reason))summary.textContent=(scheduled?'เปิด '+thaiTime(state.opensAtMs)+' · ปิด '+thaiTime(state.closesAtMs)+' · ':'')+(window.open?'เปิดรับสมัคร':'พักรับสมัคร');
  resume.textContent=scheduled?'กลับไปใช้ตารางเวลา':'เปิดรับสมัคร';resume.disabled=busy||(scheduled?!state.registrationPaused:state.registrationOpen===true);pause.disabled=busy||(scheduled?state.registrationPaused===true:state.registrationOpen!==true);reload.disabled=busy;for(const el of form.elements)el.disabled=busy;
 }
 async function run(data,success){if(!active()||busy)return;busy=true;draw();message.textContent='กำลังบันทึก…';try{const result=await client.operate({eventId:event.id,...data});if(!active())return;if((result.event.scheduleVersion||0)>=(state.scheduleVersion||0))state=result.event;offset=result.serverNow-Date.now();fill();message.textContent=success}catch(error){if(active())message.textContent=error.message||'บันทึกไม่ได้ กรุณาลองใหม่'}finally{busy=false;draw()}}
 form.oninput=()=>{dirty=true;fields()};form.onchange=()=>{dirty=true;fields()};
 form.onsubmit=e=>{e.preventDefault();const settings={mode:form.elements.mode.value};if(settings.mode==='scheduled'){settings.opensAtMs=fromThaiInput(form.elements.start.value);settings.closesAtMs=fromThaiInput(form.elements.end.value);if(!Number.isFinite(settings.opensAtMs)||!Number.isFinite(settings.closesAtMs)||settings.opensAtMs>=settings.closesAtMs||settings.closesAtMs<=Date.now()+offset){message.textContent='กรุณาระบุเวลาเปิดก่อนเวลาปิด และเวลาปิดต้องอยู่ในอนาคต';return}}
  if(!confirm('บันทึก'+(settings.mode==='scheduled'?'เวลาเปิด '+thaiTime(settings.opensAtMs)+' และปิด '+thaiTime(settings.closesAtMs):'การเปิด–ปิดด้วยตัวเอง')+'?'))return;run({action:'saveRegistrationSchedule',expectedVersion:latestVersion,settings},'บันทึกการตั้งค่าแล้ว')};
 pause.onclick=()=>{if(confirm('พักรับสมัครทันที? ตารางเวลาจะไม่เปิดรับสมัครอีกจนกว่าจะกดกลับไปใช้ตารางเวลา'))run({action:'pauseRegistration',value:true},'พักรับสมัครแล้ว')};
 resume.onclick=()=>{if(confirm(state.registrationMode==='scheduled'?'กลับไปใช้เวลาเปิด–ปิดที่กำหนดไว้?':'เปิดรับสมัครทันที?'))run({action:'pauseRegistration',value:false},'บันทึกแล้ว')};
 reload.onclick=()=>{if(!dirty||confirm('โหลดข้อมูลล่าสุดและยกเลิกข้อมูลที่ยังไม่ได้บันทึก?'))run({action:'registrationSettings'},'โหลดการตั้งค่าล่าสุดแล้ว')};
 fill();draw();const timer=setInterval(draw,1000);
 return {update(next){if(!active()||next?.id!==event.id||(next.scheduleVersion||0)<(state.scheduleVersion||0))return;state={...next};if(!dirty&&!busy)fill();else if((next.scheduleVersion||0)!==latestVersion&&!busy)message.textContent='มีผู้เปลี่ยนการตั้งค่าแล้ว กรุณาโหลดการตั้งค่าล่าสุดก่อนบันทึก';draw()},dispose(){disposed=true;clearInterval(timer);panel.remove()}};
}
